Option Default Used for Scheme client-go's <code>scheme.Scheme</code> Built-in Kubernetes types; register custom types yourself HTTPClient <code>rest.HTTPClientFor(config)</code> Shared API transport MapperProvider <code>apiutil.NewDynamicRESTMapper</code> Discovery and REST mappings NewClient <code>client.New</code> Cache-backed read/write client NewCache <code>cache.New</code> Informer cache newRecorderProvider <code>intrec.NewProvider</code> Event recorders Logger <code>logf.RuntimeLog.WithName("cluster")</code> Cluster logging <p>The broadcaster defaults support both the legacy record broadcaster and the events broadcaster. The defaulting implementation is:</p> <pre><code>func setOptionsDefaults(options Options, config *rest.Config) (Options, error) {
    if options.HTTPClient == nil {
        var err error
        options.HTTPClient, err = rest.HTTPClientFor(config)
        if err != nil {
            return options, err
        }
    }

    if options.Scheme == nil {
        options.Scheme = scheme.Scheme
    }

    if options.MapperProvider == nil {
        options.MapperProvider = apiutil.NewDynamicRESTMapper
    }

    if options.NewClient == nil {
        options.NewClient = client.New
    }

    if options.NewCache == nil {
        options.NewCache = cache.New
    }

    if options.newRecorderProvider == nil {
        options.newRecorderProvider = intrec.NewProvider
    }

    evtCl, err := eventsv1client.NewForConfigAndClient(config, options.HTTPClient)
    if err != nil {
        return options, err
    }

    if options.EventBroadcaster == nil {
        options.makeBroadcaster = func() (record.EventBroadcaster, events.EventBroadcaster, bool) {
            return record.NewBroadcaster(), events.NewBroadcaster(&amp;events.EventSinkImpl{Interface: evtCl}), true
        }
    } else {
        options.makeBroadcaster = func() (record.EventBroadcaster, events.EventBroadcaster, bool) {
            return options.EventBroadcaster, events.NewBroadcaster(&amp;events.EventSinkImpl{Interface: evtCl}), false
        }
    }

    if options.Logger.GetSink() == nil {
        options.Logger = logf.RuntimeLog.WithName("cluster")
    }

    return options, nil
}
